// Package pvehook receives Proxmox VE's notifications (docs/plan/14-v0.4.md,
// "PVE notifications"; decision 11). PVE 8.1 and later send notifications
// through targets; its webhook target (PVE 8.3 and later) can send custom
// headers but can't sign a body, so a shared secret in a header is the
// proof: one per Proxmox instance, generated by the hub, kept in the vault
// and shown once.
//
// The body is untrusted data. It's read (up to 64 KiB) and thrown away: a
// notification only makes the hub sync that instance now, rate-limited,
// instead of at its next poll. Nothing in it is parsed, stored or shown.
package pvehook

import (
	"context"
	"crypto/rand"
	"crypto/sha256"
	"crypto/subtle"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"errors"
	"io"
	"log/slog"
	"net/http"
	"regexp"
	"strconv"
	"sync"
	"time"

	"dash.cha.sh/internal/audit"
	"dash.cha.sh/internal/authz"
	"dash.cha.sh/internal/httpx"
	"dash.cha.sh/internal/msg"
	"dash.cha.sh/internal/runtime"
	"dash.cha.sh/internal/store"
	"dash.cha.sh/internal/vault"
)

// Header is the header PVE's webhook target sends the secret in.
const Header = "X-Chadash-Webhook-Secret"

// Integration is the integration whose instances take notifications.
const Integration = "proxmox"

// PathPrefix is where an instance's webhook answers.
const PathPrefix = "/api/hooks/pve/"

const (
	// maxBody bounds a notification's body; PVE's are a few kilobytes.
	maxBody = 64 << 10
	// syncEvery is how often notifications may make one instance sync: a
	// backup night sends many at once, and one sync reads them all.
	syncEvery = 15 * time.Second
	// refusalWindow: the first refusal per instance in it is audited.
	refusalWindow = 10 * time.Minute
)

// instanceRE is what an instance ID can look like in the path.
var instanceRE = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._-]{0,99}$`)

// Instances is the part of the runtime the webhook uses.
type Instances interface {
	Get(id string) (runtime.InstanceView, error)
	Refresh(id string) error
}

// Options configure the service.
type Options struct {
	Store     *store.Store
	Vault     *vault.Vault
	Instances Instances
	Proxies   httpx.Proxies
	Log       *slog.Logger
	Now       func() time.Time
}

// Service is the webhook and its secrets.
type Service struct {
	st      *store.Store
	vault   *vault.Vault
	inst    Instances
	proxies httpx.Proxies
	log     *slog.Logger
	now     func() time.Time

	// Audit records secret changes and the first refusal per window.
	Audit *authz.Recorder

	perIP   *httpx.Limiter
	perInst *httpx.Limiter

	mu       sync.Mutex
	lastSync map[string]time.Time
	refusals map[string]*refusals
}

type refusals struct {
	count int
	since time.Time
}

// New returns the service.
func New(o Options) *Service {
	s := &Service{st: o.Store, vault: o.Vault, inst: o.Instances, proxies: o.Proxies, log: o.Log, now: o.Now,
		perIP:    httpx.NewLimiter(30, 2*time.Second),
		perInst:  httpx.NewLimiter(20, 3*time.Second),
		lastSync: map[string]time.Time{}, refusals: map[string]*refusals{}}
	if s.log == nil {
		s.log = slog.New(slog.DiscardHandler)
	}
	if s.now == nil {
		s.now = time.Now
	}
	return s
}

// Register mounts the routes. Who may call each is decided by
// internal/authz/routes.go: the webhook is a Signature route (the handler
// checks the secret), the secret's routes are admin+, like the instance.
//
//	POST   /api/hooks/pve/{instance}                      PVE's notification → 202 {"status": "queued"|"coalesced"|"not_running"}
//	GET    /api/integrations/instances/{id}/pve-hook      → {instance, set, path, header, created_at?, last_used_at?}
//	POST   /api/integrations/instances/{id}/pve-hook      a new secret, replacing any → the same plus {secret}, shown once
//	DELETE /api/integrations/instances/{id}/pve-hook      → 204; the webhook refuses everything until a new one
func (s *Service) Register(mux *http.ServeMux, session func(http.Handler) http.Handler) {
	mux.HandleFunc("POST /api/hooks/pve/{instance}", s.handleHook)
	mux.Handle("GET /api/integrations/instances/{id}/pve-hook", session(http.HandlerFunc(s.handleGet)))
	mux.Handle("POST /api/integrations/instances/{id}/pve-hook", session(http.HandlerFunc(s.handleRotate)))
	mux.Handle("DELETE /api/integrations/instances/{id}/pve-hook", session(http.HandlerFunc(s.handleDelete)))
}

func secretName(instance string) string { return "hooks/pve/" + instance }
func metaKey(instance string) string    { return "pvehook." + instance }

// newSecret is 256 random bits, as hex.
func newSecret() string {
	b := make([]byte, 32)
	_, _ = io.ReadFull(rand.Reader, b)
	return hex.EncodeToString(b)
}

// ── POST /api/hooks/pve/{instance} ───────────────────────────────────────

func unauthorized(w http.ResponseWriter) {
	httpx.Say(w, http.StatusUnauthorized, "unauthorized", msg.New("pvehook.unauthorized"))
}

func tooMany(w http.ResponseWriter, wait time.Duration) {
	w.Header().Set("Retry-After", strconv.Itoa(int(wait.Seconds())+1))
	httpx.Say(w, http.StatusTooManyRequests, "rate_limited", msg.New("pvehook.rate_limited"))
}

func (s *Service) handleHook(w http.ResponseWriter, r *http.Request) {
	ip := s.proxies.ClientIP(r)
	if ok, wait := s.perIP.Allow(httpx.ClientKey(ip)); !ok {
		tooMany(w, wait)
		return
	}
	// The body first, whatever the instance: a real one and a made-up one
	// answer alike until the secret is checked.
	if _, err := io.Copy(io.Discard, http.MaxBytesReader(w, r.Body, maxBody)); err != nil {
		if _, ok := errors.AsType[*http.MaxBytesError](err); ok {
			httpx.Say(w, http.StatusRequestEntityTooLarge, "too_large", msg.New("pvehook.too_large"))
			return
		}
		httpx.Say(w, http.StatusBadRequest, "bad_request", msg.New("pvehook.bad_body"))
		return
	}
	id := r.PathValue("instance")
	if !instanceRE.MatchString(id) || s.inst == nil || s.vault == nil {
		unauthorized(w)
		return
	}
	in, err := s.inst.Get(id)
	if err != nil || in.Integration != Integration {
		// Unknown, or not Proxmox: the same answer as a wrong secret, and
		// not audited (made-up IDs would fill the log).
		unauthorized(w)
		return
	}
	ctx := r.Context()
	got := r.Header.Get(Header)
	secret, err := s.vault.Get(ctx, secretName(id))
	switch {
	case errors.Is(err, vault.ErrNotFound):
		s.refused(r, id, ip.String(), "no secret is set for this instance")
		unauthorized(w)
		return
	case err != nil:
		s.log.Error("pvehook: read a secret", "instance", id, "err", err)
		unauthorized(w)
		return
	case got == "":
		clear(secret)
		s.refused(r, id, ip.String(), "the secret header is missing")
		unauthorized(w)
		return
	}
	a, b := sha256.Sum256([]byte(got)), sha256.Sum256(secret)
	clear(secret)
	if subtle.ConstantTimeCompare(a[:], b[:]) != 1 {
		s.refused(r, id, ip.String(), "the secret is wrong")
		unauthorized(w)
		return
	}
	// Per instance only once the secret matched, so wrong guesses can't use
	// up what PVE itself may send.
	if ok, wait := s.perInst.Allow(id); !ok {
		tooMany(w, wait)
		return
	}
	s.touch(context.WithoutCancel(ctx), id)
	httpx.WriteJSON(w, http.StatusAccepted, map[string]string{"status": s.sync(id)})
}

// sync makes the instance sync now, at most once per syncEvery.
func (s *Service) sync(id string) string {
	now := s.now()
	s.mu.Lock()
	if last, ok := s.lastSync[id]; ok && now.Sub(last) < syncEvery {
		s.mu.Unlock()
		return "coalesced"
	}
	s.lastSync[id] = now
	s.mu.Unlock()
	if err := s.inst.Refresh(id); err != nil {
		return "not_running"
	}
	return "queued"
}

// refused counts a refusal and audits the first per instance in each
// window as integration.pve_hook.refused, with the reason and never the
// headers or the body.
func (s *Service) refused(r *http.Request, id, ip, reason string) {
	now := s.now()
	s.mu.Lock()
	f := s.refusals[id]
	if f == nil {
		f = &refusals{}
		s.refusals[id] = f
	}
	f.count++
	first := f.since.IsZero() || now.Sub(f.since) >= refusalWindow
	if first {
		f.since = now
	}
	n := f.count
	s.mu.Unlock()
	if !first || s.Audit == nil || s.Audit.Log == nil {
		return
	}
	params, _ := json.Marshal(map[string]any{"instance": id, "reason": reason, "refusals": n})
	m := msg.New("pvehook.refused", "reason", reason)
	if _, err := s.Audit.Log.Append(context.WithoutCancel(r.Context()), audit.Entry{
		Actor:  audit.Actor{Kind: authz.KindAnonymous, Name: "pve webhook", Via: "hook", IP: ip},
		Action: ActionRefused, Target: "integration:" + id, Params: params, Result: audit.Refused,
		Error: &audit.Error{Code: "unauthorized", Message: m.Text()},
	}); err != nil {
		s.log.Error("pvehook: audit a refusal", "instance", id, "err", err)
	}
}

// ActionRefused is the audit action of a refused notification.
const ActionRefused = "integration.pve_hook.refused"

// ── the secret ───────────────────────────────────────────────────────────

// meta is what the hub keeps beside the secret, in its settings.
type meta struct {
	CreatedAt  int64  `json:"created_at"`
	CreatedBy  string `json:"created_by,omitempty"`
	LastUsedAt int64  `json:"last_used_at,omitempty"`
}

func (s *Service) readMeta(ctx context.Context, id string) (meta, bool, error) {
	var raw string
	err := s.st.Reader().QueryRowContext(ctx, `SELECT value FROM settings WHERE key = ?`, metaKey(id)).Scan(&raw)
	if errors.Is(err, sql.ErrNoRows) {
		return meta{}, false, nil
	}
	if err != nil {
		return meta{}, false, err
	}
	var m meta
	_ = json.Unmarshal([]byte(raw), &m)
	return m, true, nil
}

func (s *Service) writeMeta(ctx context.Context, id string, m meta) error {
	b, _ := json.Marshal(m)
	_, err := s.st.Writer().ExecContext(ctx, `INSERT INTO settings (key, value, updated_at) VALUES (?, ?, ?)
		ON CONFLICT (key) DO UPDATE SET value = excluded.value, updated_at = excluded.updated_at`, metaKey(id), string(b), s.now().UnixMilli())
	return err
}

// touch records the webhook's last accepted request.
func (s *Service) touch(ctx context.Context, id string) {
	m, ok, err := s.readMeta(ctx, id)
	if err != nil || !ok {
		return
	}
	m.LastUsedAt = s.now().UnixMilli()
	if err := s.writeMeta(ctx, id, m); err != nil {
		s.log.Warn("pvehook: record a notification", "instance", id, "err", err)
	}
}

// View is the secret's state, as the routes answer it.
type View struct {
	Instance string `json:"instance"`
	Set      bool   `json:"set"`
	// Path is where PVE sends notifications, relative to the hub's
	// address; Header the header it sends the secret in.
	Path       string `json:"path"`
	Header     string `json:"header"`
	CreatedAt  *int64 `json:"created_at,omitempty"`
	LastUsedAt *int64 `json:"last_used_at,omitempty"`
	// Secret is only in the answer that made it.
	Secret string `json:"secret,omitempty"`
}

func (s *Service) view(ctx context.Context, id string) (View, error) {
	v := View{Instance: id, Path: PathPrefix + id, Header: Header}
	m, ok, err := s.readMeta(ctx, id)
	if err != nil {
		return v, err
	}
	if ok && s.vault != nil {
		if _, err := s.vault.Get(ctx, secretName(id)); err == nil {
			v.Set = true
			v.CreatedAt = &m.CreatedAt
			if m.LastUsedAt > 0 {
				v.LastUsedAt = &m.LastUsedAt
			}
		}
	}
	return v, nil
}

// instance answers 404 or 422 for an ID the routes can't serve.
func (s *Service) instance(w http.ResponseWriter, r *http.Request) (string, bool) {
	id := r.PathValue("id")
	if s.inst == nil || !instanceRE.MatchString(id) {
		httpx.Say(w, http.StatusNotFound, "not_found", msg.New("pvehook.not_found"))
		return "", false
	}
	in, err := s.inst.Get(id)
	if err != nil {
		httpx.Say(w, http.StatusNotFound, "not_found", msg.New("pvehook.not_found"))
		return "", false
	}
	if in.Integration != Integration {
		httpx.Say(w, http.StatusUnprocessableEntity, "not_proxmox", msg.New("pvehook.not_proxmox"))
		return "", false
	}
	if s.vault == nil {
		httpx.Say(w, http.StatusServiceUnavailable, "unavailable", msg.New("pvehook.no_vault"))
		return "", false
	}
	return id, true
}

func (s *Service) handleGet(w http.ResponseWriter, r *http.Request) {
	id, ok := s.instance(w, r)
	if !ok {
		return
	}
	v, err := s.view(r.Context(), id)
	if err != nil {
		s.log.Error("pvehook: read", "instance", id, "err", err)
		httpx.Say(w, http.StatusInternalServerError, "internal", msg.New("hub.internal_error"))
		return
	}
	httpx.WriteJSON(w, http.StatusOK, v)
}

func (s *Service) handleRotate(w http.ResponseWriter, r *http.Request) {
	id, ok := s.instance(w, r)
	if !ok {
		return
	}
	ctx := r.Context()
	before, err := s.view(ctx, id)
	if err != nil {
		s.log.Error("pvehook: read", "instance", id, "err", err)
		httpx.Say(w, http.StatusInternalServerError, "internal", msg.New("hub.internal_error"))
		return
	}
	secret := newSecret()
	a, _ := authz.ActorFrom(r)
	if err := s.vault.Put(ctx, secretName(id), []byte(secret)); err != nil {
		s.log.Error("pvehook: store a secret", "instance", id, "err", err)
		httpx.Say(w, http.StatusInternalServerError, "failed", msg.New("pvehook.failed"))
		return
	}
	if err := s.writeMeta(ctx, id, meta{CreatedAt: s.now().UnixMilli(), CreatedBy: a.ID}); err != nil {
		s.log.Error("pvehook: store a secret", "instance", id, "err", err)
		httpx.Say(w, http.StatusInternalServerError, "failed", msg.New("pvehook.failed"))
		return
	}
	s.mu.Lock()
	delete(s.refusals, id)
	s.mu.Unlock()
	s.Audit.Change(r, authz.Audited["POST /api/integrations/instances/{id}/pve-hook"], "integration:"+id, map[string]any{"replaced": before.Set}, authz.T1, nil)
	v, err := s.view(ctx, id)
	if err != nil {
		httpx.Say(w, http.StatusInternalServerError, "internal", msg.New("hub.internal_error"))
		return
	}
	v.Secret = secret
	w.Header().Set("Cache-Control", "no-store")
	httpx.WriteJSON(w, http.StatusOK, v)
}

func (s *Service) handleDelete(w http.ResponseWriter, r *http.Request) {
	id, ok := s.instance(w, r)
	if !ok {
		return
	}
	ctx := r.Context()
	err := s.vault.Delete(ctx, secretName(id))
	if errors.Is(err, vault.ErrNotFound) {
		httpx.Say(w, http.StatusNotFound, "not_set", msg.New("pvehook.not_set"))
		return
	}
	if err != nil {
		s.log.Error("pvehook: delete a secret", "instance", id, "err", err)
		httpx.Say(w, http.StatusInternalServerError, "failed", msg.New("pvehook.failed"))
		return
	}
	if _, err := s.st.Writer().ExecContext(ctx, `DELETE FROM settings WHERE key = ?`, metaKey(id)); err != nil {
		s.log.Warn("pvehook: forget a secret's dates", "instance", id, "err", err)
	}
	s.Audit.Change(r, authz.Audited["DELETE /api/integrations/instances/{id}/pve-hook"], "integration:"+id, nil, authz.T1, nil)
	w.WriteHeader(http.StatusNoContent)
}
